\label{mainthm2}
If $(X,G)$ has $\mathrm{APP}_G$, then every invariant measure is almost
entropy-approximable.

\label{mainthm3}
If $(X,G)$ has $\mathrm{APP}_G$ and is asymptotically entropy expansive, then:
\begin{enumerate}
\item Every invariant measure is entropy-approximable.
\item The system $(X,G)$ is entropy-generic. Equivalently, for every
$0\leq\alpha<h(X,G)$, the set $\mathcal M_e(X,G,\alpha)$ is residual in
$\mathcal M^\alpha(X,G)$.
\end{enumerate}

\label{oldtiling1}
Let $0<\kappa\leq1/2$. There exists an integer $t_0=t_0(\kappa)\geq1$
such that, for every $t\geq t_0$, the following holds.
If nonempty finite sets $T_1,\ldots,T_t,S\subset G$ satisfy
\[
\begin{aligned}
\frac{|\partial_{T_j}T_i|}{|T_i|}&\leq\kappa^{2t}
&& (1\leq j<i\leq t),\\
\frac{|\partial_{T_j}S|}{|S|}&\leq\kappa^{2t}
&& (1\leq j\leq t),
\end{aligned}
\]
then  $S$  can be $\kappa$-quasitiled by$T_1,\ldots,T_t$ .

\label{finiteAPPimpliesAPP}
  The finite approximate product property is equivalent to the approximate
  product property.

Apply Lemma~\ref{measures3} on each $P_i$, take the convex combination
with weights $|P_i|/|\bigcup_jP_j|$, and apply Lemma~\ref{measures1}
to include the uncovered part of $F$.

\label{lem:mistake-code}
For $0<\delta<1/2$ and every positive integer $N$,
\begin{equation}\label{eq:finite-mistake-count}
\sum_{j=0}^{\lfloor\delta N\rfloor}\binom Nj\leq e^{H_{\mathrm b}(\delta)N}.
\end{equation}
For a nonempty finite alphabet $Q$, the number of choices of at most
$\delta N$ sites and their $Q$-values is at most
$\exp((H_{\mathrm b}(\delta)+\delta\log|Q|)N)$.

\label{lem:admissible-subtiles}
Fix $K\in \mathcal F(G)$ with $e_G\in K$, $\eta_K>0$, and $0<\kappa<1/4$ such that
\begin{equation}\label{eq:trim-budget}
\frac{3|K|\kappa}{1-3\kappa}<\frac{\eta_K}{2}.
\end{equation}
Given a F{\o}lner sequence $(F_n)$ and a lower bound $L$ on
shape cardinalities and $N\geq 1$, there are indices $n_1<\cdots<n_t$ larger than $N$ 
and a zero-entropy exact tiling $\mathcal T$ with shape family $\mathcal S$
such that $|S|\geq L$ for all $S\in\mathcal S$, and every shape has
pairwise disjoint subtiles $J_{S,i,c}c\subset S$, $c\in C_{S,i}$, with
\begin{equation}\label{eq:good-cover-new}
\begin{gathered}
J_{S,i,c}\subset F_{n_i},\qquad
|J_{S,i,c}|>(1-3\kappa)|F_{n_i}|,\\
\left|\bigsqcup_{i,c}J_{S,i,c}c\right|>(1-4\kappa)|S|.
\end{gathered}
\end{equation}
Every $J_{S,i,c}$ is $(K,\eta_K)$-invariant. Moreover, after the finite
block family has been fixed, $\max_i|F_{n_i}|/|S|$ can be made arbitrarily
small for every final shape $S$.

\label{mainprop1}
Assume that $(X,G)$ has the approximate product property.  Let
$\mu_0\in\mathcal M_e(X,G)$ with $h_{\mu_0}(X.G)>0$ and
\[
0<h_0<h_{\mu_0}(X,G).
\]
For every $\eta_0,\beta_0,\gamma_0>0$ there exist
$\gamma\in(0,\gamma_0)$ and a nonempty compact $G$-invariant set
$\Lambda\subset X$ such that
\begin{enumerate}
\item $\mathcal M(\Lambda,G)\subset B(\mu_0,\eta_0)$;
\item $h(\Lambda,G)>h_0$;
\item $h(\Lambda,G,\gamma)<h_0+\beta_0$.
\end{enumerate}

\label{prop:entropy-generic-abstract}
Suppose that $(X,G)$ is asymptotically entropy expansive and every measure in
$\mathcal M(X,G)$ is entropy-approximable. Then $(X,G)$ is entropy-generic.

\label{lem:balanced-coloring}
In Lemma~\ref{lem:admissible-subtiles}, the final shapes can be chosen so
that their good subtiles admit colors $1,\dots,L$ with
\begin{equation}\label{eq:color-weights}
\left|w_i(S)-\frac1L\right|<5\kappa,
\qquad
w_i(S):=\frac1{|S|}\sum_{Jc\text{ of color }i}|J|.
\end{equation}
The uncolored remainder has proportion less than $4\kappa$.
